import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; Aa=df['A'].values; y=df['dA_dt'].values
V=np.var(y)
def base_amp(p,t):
    base=-(p[0]+p[1]/t+p[2]*t+p[3]*np.exp(-t))
    amp=p[4]+p[5]*t+p[6]*t**2
    return base,amp
def G1(p,t,A):
    b,a=base_amp(p,t)
    k=np.exp(np.clip(p[7]+p[8]*t,-30,30))
    return b+a*(1-np.exp(-k*np.abs(A)**p[9]))*np.exp(-p[10]*A)
def G2(p,t,A):
    b,a=base_amp(p,t)
    K=np.exp(np.clip(p[7]+p[8]*t,-30,30))
    An=np.abs(A)**p[9]
    return b+a*(An/(K**p[9]+An))*np.exp(-p[10]*A)
rng=np.random.default_rng(2)
for name,f in [('G1',G1),('G2',G2)]:
    best=(np.inf,None)
    for s in range(70):
        p0=rng.normal(0,1,11)
        try:
            r=least_squares(lambda p: f(p,t,Aa)-y,p0,max_nfev=2000)
            nm=np.mean(r.fun**2)/V
            if np.isfinite(nm) and nm<best[0]: best=(nm,r.x)
        except Exception: pass
    print(name,'%.3e'%best[0],np.round(best[1],4).tolist())
